INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5959435, 870732, 15711, '<td valign="top">I like this so much.  Beautiful use of light and negative space.</td>', 'I like this so much.  Beautiful use of light and negative space.', '2010-04-21 01:22:30.000000', NULL, 1),
(5959453, 871279, 30861, '<td valign="top">LOL. Refreshing... Have you actually read the book? Just curious...</td>', 'LOL. Refreshing... Have you actually read the book? Just curious...', '2010-04-21 01:24:32.000000', NULL, 1),
(5959458, 868521, 15711, '<td valign="top">This is sweet and beautiful but to me Zen is about meditation and spirituality.  Nonetheless, this is a fabulous image.</td>', 'This is sweet and beautiful but to me Zen is about meditation and spirituality.  Nonetheless, this is a fabulous image.', '2010-04-21 01:24:49.000000', NULL, 1),
(5959469, 867637, 73981, '<td valign="top">You''re gonna get dinged for the text on your entry...otherwise a nice shot 7</td>', 'You''re gonna get dinged for the text on your entry...otherwise a nice shot 7', '2010-04-21 01:25:42.000000', NULL, 1),
(5959473, 871580, 15711, '<td valign="top">Really beautiful.  The lighting is excellent.</td>', 'Really beautiful.  The lighting is excellent.', '2010-04-21 01:26:04.000000', NULL, 1),
(5959597, 871464, 116499, '<td valign="top">This image is very dark. It also uses kind of cliche images (rocks and a flower) of ''zen'' and the elements probably should be on a side of the photo not the center; however, I think it''s interesting especially because of the water coming in from the left and the reflection of the flower at the bottom.</td>', 'This image is very dark. It also uses kind of cliche images (rocks and a flower) of ''zen'' and the elements probably should be on a side of the photo not the center; however, I think it''s interesting especially because of the water coming in from the left and the reflection of the flower at the bottom.', '2010-04-21 01:43:08.000000', NULL, 1),
(5959606, 870575, 116499, '<td valign="top">I really like this image; the color is gorgeous and the silhouette is nice, but you might have been better off cutting off the ground or minimizing it somehow.</td>', 'I really like this image; the color is gorgeous and the silhouette is nice, but you might have been better off cutting off the ground or minimizing it somehow.', '2010-04-21 01:44:33.000000', NULL, 1),
(5959618, 870419, 113142, '<td valign="top">Very minimal, a good thing.</td>', 'Very minimal, a good thing.', '2010-04-21 01:45:56.000000', NULL, 1),
(5959620, 871416, 116499, '<td valign="top">A smaller aperture would have been better, but the overall concept is well executed.</td>', 'A smaller aperture would have been better, but the overall concept is well executed.', '2010-04-21 01:46:03.000000', NULL, 1),
(5959633, 871578, 113142, '<td valign="top">Hard to pick a center for DOF when macro. If you are inverting the lens, try to set the f/ higher and remove the lens while depressing the DOF preview button. That''ll give greater DOF. I assume no responsibility for lens damage! JK.</td>', 'Hard to pick a center for DOF when macro. If you are inverting the lens, try to set the f/ higher and remove the lens while depressing the DOF preview button. That''ll give greater DOF. I assume no responsibility for lens damage! JK.', '2010-04-21 01:48:14.000000', NULL, 1),
(5959638, 868572, 113142, '<td valign="top">Out of focus on purpose?</td>', 'Out of focus on purpose?', '2010-04-21 01:48:52.000000', NULL, 1),
(5959642, 871104, 116499, '<td valign="top">This image tricked my eye for a few seconds, which gave me pause. I like this image, but there''s too much of the cat''s body in frame on the right and it distracts from the dramatic light you captured so well on the front of its body.</td>', 'This image tricked my eye for a few seconds, which gave me pause. I like this image, but there''s too much of the cat''s body in frame on the right and it distracts from the dramatic light you captured so well on the front of its body.', '2010-04-21 01:49:24.000000', NULL, 1),
(5959645, 868463, 113142, '<td valign="top">Good colors, quite surreal. Too much to bring me zen, but then again this is supposed to be YOUR zen.</td>', 'Good colors, quite surreal. Too much to bring me zen, but then again this is supposed to be YOUR zen.', '2010-04-21 01:50:14.000000', NULL, 1),
(5959651, 870759, 113142, '<td valign="top">Did you ever play that independent game "cloud?" very serene, like this photo. Nice 1/3 ratio.</td>', 'Did you ever play that independent game "cloud?" very serene, like this photo. Nice 1/3 ratio.', '2010-04-21 01:51:03.000000', NULL, 1),
(5959653, 869613, 113142, '<td valign="top">IR filter? nice touch, for stars I guess the sky could have been darkened a bit.</td>', 'IR filter? nice touch, for stars I guess the sky could have been darkened a bit.', '2010-04-21 01:51:44.000000', NULL, 1),
(5959657, 870468, 113142, '<td valign="top">Sweet, but something''s missing. Interesting choice of B/W conversion.</td>', 'Sweet, but something''s missing. Interesting choice of B/W conversion.', '2010-04-21 01:52:43.000000', NULL, 1),
(5959663, 869300, 113142, '<td valign="top">Maybe if you shifted to the OTHER 1/3, this wouldn''t seem so far away and detached. Nice level, B/W, and subjet.</td>', 'Maybe if you shifted to the OTHER 1/3, this wouldn''t seem so far away and detached. Nice level, B/W, and subjet.', '2010-04-21 01:54:25.000000', NULL, 1),
(5959665, 871067, 116499, '<td valign="top">Nice use of muted colors, including the fruit. The many textures of the image work pretty well together - the only one that seems to clash is the tablecloth.</td>', 'Nice use of muted colors, including the fruit. The many textures of the image work pretty well together - the only one that seems to clash is the tablecloth.', '2010-04-21 01:54:31.000000', NULL, 1),
(5959668, 869234, 113142, '<td valign="top">I tried to find one of these myself! glad I didn''t, yours is nice.</td>', 'I tried to find one of these myself! glad I didn''t, yours is nice.', '2010-04-21 01:55:04.000000', NULL, 1),
(5959676, 871109, 113142, '<td valign="top">I like the idea, but I''m so sorry to say that I can tell you used a hose from the shape of the water above the umbrella.</td>', 'I like the idea, but I''m so sorry to say that I can tell you used a hose from the shape of the water above the umbrella.', '2010-04-21 01:56:33.000000', NULL, 1),
(5959679, 868307, 113142, '<td valign="top">I &lt;3 ladybugs. even preachy ones. gorgeous colors!</td>', 'I <3 ladybugs. even preachy ones. gorgeous colors!', '2010-04-21 01:57:31.000000', NULL, 1),
(5959682, 871549, 113142, '<td valign="top">Spring was a perfect time for a zen picture, wasn''t it?</td>', 'Spring was a perfect time for a zen picture, wasn''t it?', '2010-04-21 01:57:51.000000', NULL, 1),
(5959690, 867738, 15711, '<td valign="top">This is stellar. I don''t immediately think Zen, but your thoughtful approach made me reconsider and it''s perfect.</td>', 'This is stellar. I don''t immediately think Zen, but your thoughtful approach made me reconsider and it''s perfect.', '2010-04-21 01:59:33.000000', NULL, 1),
(5959693, 870836, 113142, '<td valign="top">First thought? WOW. this really pops. a lot. while still, somehow, maintaining a quiet dignity fitting the challenge to a "t." hope you ribbon.</td>', 'First thought? WOW. this really pops. a lot. while still, somehow, maintaining a quiet dignity fitting the challenge to a "t." hope you ribbon.', '2010-04-21 01:59:53.000000', NULL, 1),
(5959698, 868741, 113142, '<td valign="top">I love pictures of flowers. Great choice for DOF and light direction.</td>', 'I love pictures of flowers. Great choice for DOF and light direction.', '2010-04-21 02:00:43.000000', NULL, 1),
(5959700, 870991, 15711, '<td valign="top">So lovely!!! I love the white and pink on white. 8</td>', 'So lovely!!! I love the white and pink on white. 8', '2010-04-21 02:01:04.000000', NULL, 1),
(5959703, 871558, 113142, '<td valign="top">A bit garish and tilted.</td>', 'A bit garish and tilted.', '2010-04-21 02:01:15.000000', NULL, 1),
(5959706, 871101, 113142, '<td valign="top">ARRRGH! direct competition! Very nice picture, regardless!</td>', 'ARRRGH! direct competition! Very nice picture, regardless!', '2010-04-21 02:01:57.000000', NULL, 1),
(5959710, 870737, 113142, '<td valign="top">Balance in color and reflection! nice!</td>', 'Balance in color and reflection! nice!', '2010-04-21 02:03:19.000000', NULL, 1),
(5959712, 870740, 116499, '<td valign="top">Great light, depth of field, and texture, but s/he looks pretty angry.</td>', 'Great light, depth of field, and texture, but s/he looks pretty angry.', '2010-04-21 02:04:05.000000', NULL, 1),
(5959713, 871211, 113142, '<td valign="top">Beautiful still life.</td>', 'Beautiful still life.', '2010-04-21 02:04:13.000000', NULL, 1),
