(5960679, 870465, 103310, '<td valign="top">For me ZEN is a striving towards rest, stability and luck. This photograph is splendid of advancement and colour. But I find no rest in this picture. The picture brings me a feeling of threat and disorder, what I want flee by means of ZEN.</td>', 'For me ZEN is a striving towards rest, stability and luck. This photograph is splendid of advancement and colour. But I find no rest in this picture. The picture brings me a feeling of threat and disorder, what I want flee by means of ZEN.', '2010-04-21 09:42:52.000000', NULL, 1),
(5960681, 871016, 7889, '<td valign="top">Oh yes, very good! Dont know what the rest of dpc think but this is excellent, love the processing on this.</td>', 'Oh yes, very good! Dont know what the rest of dpc think but this is excellent, love the processing on this.', '2010-04-21 09:43:52.000000', NULL, 1),
(5960685, 871605, 7889, '<td valign="top">Really excellent photo, I just love the movement and the colours. Good luck.</td>', 'Really excellent photo, I just love the movement and the colours. Good luck.', '2010-04-21 09:46:29.000000', NULL, 1),
(5960690, 868617, 15711, '<td valign="top">WOW  that''s just about the prettiest landscape.  I love the gray to brown duotone.  Gorgeous.</td>', 'WOW  that''s just about the prettiest landscape.  I love the gray to brown duotone.  Gorgeous.', '2010-04-21 09:49:39.000000', NULL, 1),
(5960694, 870292, 65234, '<td valign="top">Very painterly effect, which ordinarily I don''t care for, but I think this effect in this challenge works extremely well.  Almost like an Oriental watercolor ... well, duotone variation, anyway.</td>', 'Very painterly effect, which ordinarily I don''t care for, but I think this effect in this challenge works extremely well.  Almost like an Oriental watercolor ... well, duotone variation, anyway.', '2010-04-21 09:50:33.000000', NULL, 1),
(5960695, 869085, 15711, '<td valign="top">Gorgeous colors.  I like the narrow depth of field.</td>', 'Gorgeous colors.  I like the narrow depth of field.', '2010-04-21 09:50:47.000000', NULL, 1),
(5960696, 870575, 15711, '<td valign="top">Much  better than my attempt.  I like the BG colors as well. Very serene.</td>', 'Much  better than my attempt.  I like the BG colors as well. Very serene.', '2010-04-21 09:51:22.000000', NULL, 1),
(5960699, 870768, 15711, '<td valign="top">I might have cropped it tighter from the left and above.  The table in the upper right is a touch distracting but doesn''t really take away too much from this beautiful peaceful moment.</td>', 'I might have cropped it tighter from the left and above.  The table in the upper right is a touch distracting but doesn''t really take away too much from this beautiful peaceful moment.', '2010-04-21 09:52:13.000000', NULL, 1),
