(5963821, 868949, 73452, '<td valign="top">Love the concept.  Very unique.</td>', 'Love the concept.  Very unique.', '2010-04-22 16:07:19.000000', NULL, 1),
(5963822, 871533, 73452, '<td valign="top">I wish the twig and bird were more in frame, but this may have been what you were going for.  I suppose its a matter of personal taste here.  AMazing colors, non-theless.</td>', 'I wish the twig and bird were more in frame, but this may have been what you were going for.  I suppose its a matter of personal taste here.  AMazing colors, non-theless.', '2010-04-22 16:07:51.000000', NULL, 1),
