(5963827, 871474, 73452, '<td valign="top">INteresting find.  Brave of you as well to chose a flower thats not blossomed, very interesting.  Nice contrast between the greens and the pinks.</td>', 'INteresting find.  Brave of you as well to chose a flower thats not blossomed, very interesting.  Nice contrast between the greens and the pinks.', '2010-04-22 16:08:24.000000', NULL, 1),
(5963829, 871371, 73452, '<td valign="top">Not a fan of the border, and the picture has a strange oversharpened taste to it.</td>', 'Not a fan of the border, and the picture has a strange oversharpened taste to it.', '2010-04-22 16:08:49.000000', NULL, 1),
(5963830, 870974, 73452, '<td valign="top">I wish the horizon was level.  Otherwise, a very nicely lit and composed image.</td>', 'I wish the horizon was level.  Otherwise, a very nicely lit and composed image.', '2010-04-22 16:09:17.000000', NULL, 1),
