(5965625, 868262, 115814, '<td valign="top">Very nice. This works for me on several levels... including connection to the challenge theme. The placement of the subject so close to the bottom of the frame is nicely offset by the effect of the gradient. I like it better each time I see it.</td>', 'Very nice. This works for me on several levels... including connection to the challenge theme. The placement of the subject so close to the bottom of the frame is nicely offset by the effect of the gradient. I like it better each time I see it.', '2010-04-23 19:01:39.000000', NULL, 1),
(5965634, 871211, 115814, '<td valign="top">This is really striking. And... it gets better with each viewing. The distinct color highlight changes on the inside of the bowl''s rim are especially effective. And... I''m intrigued by what reflected orb in the water may actually be. Works on lots of levels. Kudos.</td>', 'This is really striking. And... it gets better with each viewing. The distinct color highlight changes on the inside of the bowl''s rim are especially effective. And... I''m intrigued by what reflected orb in the water may actually be. Works on lots of levels. Kudos.', '2010-04-23 19:05:38.000000', NULL, 1),
(5965686, 871596, 115096, '<td valign="top">Hahaha very coool!</td>', 'Hahaha very coool!', '2010-04-23 20:06:51.000000', NULL, 1),
(5965713, 868617, 116247, '<td valign="top">Beautiful- love to know where this photograph was taken</td>', 'Beautiful- love to know where this photograph was taken', '2010-04-23 20:43:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5965717, 870741, 63633, '<td valign="top">Genius. 10.</td>', 'Genius. 10.', '2010-04-23 20:46:03.000000', NULL, 1),
(5965836, 871095, 116976, '<td valign="top">I absolutely love the colors in this photo. It is such a beautiful shot.</td>', 'I absolutely love the colors in this photo. It is such a beautiful shot.', '2010-04-23 22:19:16.000000', NULL, 1),
(5965840, 870017, 116976, '<td valign="top">I can see myself relaxing on the rock face in the foreground, contemplating life. A beautiful shot.</td>', 'I can see myself relaxing on the rock face in the foreground, contemplating life. A beautiful shot.', '2010-04-23 22:22:35.000000', NULL, 1),
(5965873, 870791, 115455, '<td valign="top">I think it would have been better with the top bird cropped out.</td>', 'I think it would have been better with the top bird cropped out.', '2010-04-23 22:51:21.000000', NULL, 1),
(5965875, 869348, 23317, '<td valign="top">This was one of my favorites of the challenge.  An excellent capture.  For some reason, I''m worried the 2nd shadow may detract for some.  It didn''t bother me at all, but it''s the kind of thing DPC voters will look to nitpick at times.  Well done.</td>', 'This was one of my favorites of the challenge.  An excellent capture.  For some reason, I''m worried the 2nd shadow may detract for some.  It didn''t bother me at all, but it''s the kind of thing DPC voters will look to nitpick at times.  Well done.', '2010-04-23 22:51:52.000000', NULL, 1),
(5965877, 869613, 23317, '<td valign="top">One of my two favorites of the challenge.  Beautifully peaceful.</td>', 'One of my two favorites of the challenge.  Beautifully peaceful.', '2010-04-23 22:52:51.000000', NULL, 1),
(5965879, 870778, 23317, '<td valign="top">Because after the 1st tee (and my first slice into the trees), it''s no longer a zen experience.  Very nice shot.  Like the mood created by the fog.</td>', 'Because after the 1st tee (and my first slice into the trees), it''s no longer a zen experience.  Very nice shot.  Like the mood created by the fog.', '2010-04-23 22:54:32.000000', NULL, 1),
(5965881, 871597, 23317, '<td valign="top">Nice perspective</td>', 'Nice perspective', '2010-04-23 22:55:37.000000', NULL, 1),
(5965929, 870737, 47852, '<td valign="top">Is the photo flipped upside down?  Great symmetry... I find myself trying to search out the differences in the two halves.</td>', 'Is the photo flipped upside down?  Great symmetry... I find myself trying to search out the differences in the two halves.', '2010-04-23 23:46:51.000000', NULL, 1),
(5965981, 870751, 115096, '<td valign="top">Way awesome! 10.5</td>', 'Way awesome! 10.5', '2010-04-24 00:32:32.000000', NULL, 1),
(5966056, 871131, 62357, '<td valign="top">I''d love to give this the score I believe it deserves.  I love this.</td>', 'I''d love to give this the score I believe it deserves.  I love this.', '2010-04-24 01:46:31.000000', NULL, 1),
(5966113, 871371, 101702, '<td valign="top">Whilst the border matches the tones perfectly, I find it distracting that items from the image bisect the border. I personally would prefer no image area outside the border.</td>', 'Whilst the border matches the tones perfectly, I find it distracting that items from the image bisect the border. I personally would prefer no image area outside the border.', '2010-04-24 04:42:03.000000', NULL, 1),
(5966124, 870737, 94241, '<td valign="top">A beautiful image, but I feel that a different crop would have added just a bit to it.<br/>Consider either (1) a square frame to enforce the sense of directionless, or (2) the rectangular frame but offset the birds downward so the bottom half feels heavier than the top half.  Right now it just feels a bit unbalanced to me.</td>', 'A beautiful image, but I feel that a different crop would have added just a bit to it.Consider either (1) a square frame to enforce the sense of directionless, or (2) the rectangular frame but offset the birds downward so the bottom half feels heavier than the top half.  Right now it just feels a bit unbalanced to me.', '2010-04-24 05:28:24.000000', NULL, 1),
(5966128, 871607, 94241, '<td valign="top">I absolutely love this composition and would consider this photo one of the best of the challenge, except one thing: fingernails.  The long fingernails make the hands look challenging and mean.</td>', 'I absolutely love this composition and would consider this photo one of the best of the challenge, except one thing: fingernails.  The long fingernails make the hands look challenging and mean.', '2010-04-24 05:53:55.000000', NULL, 1),
(5966132, 870015, 94241, '<td valign="top">Tilted horizon line?</td>', 'Tilted horizon line?', '2010-04-24 06:15:18.000000', NULL, 1),
(5966133, 868468, 94241, '<td valign="top">As awesome as the placement of the bird is, I think it detracts from the solitude of the image.</td>', 'As awesome as the placement of the bird is, I think it detracts from the solitude of the image.', '2010-04-24 06:19:54.000000', NULL, 1),
(5966134, 870697, 94241, '<td valign="top">Stunning.  Of all the stacked rocks in this show, this is my favorite.  Is that translucent rocks on top?  (9)</td>', 'Stunning.  Of all the stacked rocks in this show, this is my favorite.  Is that translucent rocks on top?  (9)', '2010-04-24 06:22:20.000000', NULL, 1),
(5966191, 871295, 23484, '<td valign="top">Beautiful. I love the softness and the over exposed look. Nice job.</td>', 'Beautiful. I love the softness and the over exposed look. Nice job.', '2010-04-24 09:06:45.000000', NULL, 1),
