(5966223, 871287, 23484, '<td valign="top">Very nice simple composition.9</td>', 'Very nice simple composition.9', '2010-04-24 09:30:19.000000', NULL, 1),
(5966224, 868062, 23484, '<td valign="top">Beautiful colors.</td>', 'Beautiful colors.', '2010-04-24 09:31:00.000000', NULL, 1),
