(5966297, 869348, 67152, '<td valign="top">amazing composition and delivery</td>', 'amazing composition and delivery', '2010-04-24 10:22:56.000000', NULL, 1),
(5966299, 871605, 67152, '<td valign="top">dancing is exactly what i see here - lovely</td>', 'dancing is exactly what i see here - lovely', '2010-04-24 10:23:32.000000', NULL, 1),
(5966300, 868307, 76335, '<td valign="top">The bright, vivid colors aren''t exactly calming (zen-like). But I do love the shot. Great title too.</td>', 'The bright, vivid colors aren''t exactly calming (zen-like). But I do love the shot. Great title too.', '2010-04-24 10:23:34.000000', NULL, 1),
(5966301, 868572, 76335, '<td valign="top">I Ge Tit</td>', 'I Ge Tit', '2010-04-24 10:24:05.000000', NULL, 1),
