(5966304, 871169, 67152, '<td valign="top">fabulous set up and delivery</td>', 'fabulous set up and delivery', '2010-04-24 10:24:54.000000', NULL, 1),
(5966309, 869085, 67152, '<td valign="top">intense light and intense darkness - wonderfully seen and delivered</td>', 'intense light and intense darkness - wonderfully seen and delivered', '2010-04-24 10:26:15.000000', NULL, 1),
(5966310, 868680, 76335, '<td valign="top">A green blob against a monochrome background. I don''t get it. What is it? Is it zen?</td>', 'A green blob against a monochrome background. I don''t get it. What is it? Is it zen?', '2010-04-24 10:26:20.000000', NULL, 1),
(5966313, 870227, 76335, '<td valign="top">Bamboo is classic zen fare, I guess. Nice composition.</td>', 'Bamboo is classic zen fare, I guess. Nice composition.', '2010-04-24 10:27:19.000000', NULL, 1),
(5966315, 871280, 67152, '<td valign="top">the ability to contemplate on simple objects and find beauty in them is a gift - well done to allow us to share your insight</td>', 'the ability to contemplate on simple objects and find beauty in them is a gift - well done to allow us to share your insight', '2010-04-24 10:28:34.000000', NULL, 1),
(5966316, 871550, 76335, '<td valign="top">I really like this, and I think it does meet the challenge. The water is so still and the skyline is so distant. It doesn''t lose its intrigue, but it''s far enough away that we don''t hear its noise. The deep blues work well too. Very good.</td>', 'I really like this, and I think it does meet the challenge. The water is so still and the skyline is so distant. It doesn''t lose its intrigue, but it''s far enough away that we don''t hear its noise. The deep blues work well too. Very good.', '2010-04-24 10:29:34.000000', NULL, 1),
(5966318, 869059, 76335, '<td valign="top">Beautifully composed the way the arches of the tree limbs sort of echo the arch of the bridge.</td>', 'Beautifully composed the way the arches of the tree limbs sort of echo the arch of the bridge.', '2010-04-24 10:30:24.000000', NULL, 1),
(5966319, 871175, 76335, '<td valign="top">Original, dreamy, very zen.</td>', 'Original, dreamy, very zen.', '2010-04-24 10:30:59.000000', NULL, 1),
(5966322, 871381, 76335, '<td valign="top">Nice patterns and rhythm here.</td>', 'Nice patterns and rhythm here.', '2010-04-24 10:31:55.000000', NULL, 1),
(5966324, 871193, 76335, '<td valign="top">I''m probably not feeling the zen if he''s around. I like the limy greens in this.</td>', 'I''m probably not feeling the zen if he''s around. I like the limy greens in this.', '2010-04-24 10:32:44.000000', NULL, 1),
(5966327, 871279, 76335, '<td valign="top">Wow. How does ho DO that?</td>', 'Wow. How does ho DO that?', '2010-04-24 10:33:55.000000', NULL, 1),
(5966329, 870198, 76335, '<td valign="top">Beautifully soft. I like the delicate springtime colors.</td>', 'Beautifully soft. I like the delicate springtime colors.', '2010-04-24 10:35:18.000000', NULL, 1),
(5966332, 871275, 76335, '<td valign="top">Excellent. Fabulous composition. The intrigue comes from everything <i>not</i> in the frame.</td>', 'Excellent. Fabulous composition. The intrigue comes from everything not in the frame.', '2010-04-24 10:36:25.000000', NULL, 1),
(5966333, 871605, 76335, '<td valign="top">Great title. Wonderful energy.</td>', 'Great title. Wonderful energy.', '2010-04-24 10:36:54.000000', NULL, 1),
