(5967802, 870501, 68573, '<td valign="top">Nice image and a good layers in the compositions. Your title seems to be a tad misfit as the birds are just a small part of the image - to me it looks more like a fence image</td>', 'Nice image and a good layers in the compositions. Your title seems to be a tad misfit as the birds are just a small part of the image - to me it looks more like a fence image', '2010-04-25 12:04:29.000000', NULL, 1),
(5967811, 868992, 68573, '<td valign="top">Nice and soft</td>', 'Nice and soft', '2010-04-25 12:10:34.000000', NULL, 1),
