INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5971946, 868360, 102644, '<td valign="top">Would like to see this in B&amp;W</td>', 'Would like to see this in B&W', '2010-04-26 16:40:13.000000', NULL, 1),
(5971956, 871211, 102644, '<td valign="top">I love this images - I would have removed the orange reflection in the bowel myself :o)</td>', 'I love this images - I would have removed the orange reflection in the bowel myself :o)', '2010-04-26 16:46:09.000000', NULL, 1),
(5972006, 870468, 116489, '<td valign="top">The selective desaturation here makes it look like the deer is lying on a field of ash.</td>', 'The selective desaturation here makes it look like the deer is lying on a field of ash.', '2010-04-26 17:04:46.000000', NULL, 1),
(5972582, 867931, 115671, '<td valign="top">It seems a little bit blurry to me, maybe it was out of focus or the shutter speed was too slow? Anyway, nice photo, doesn''t "shout" zen but it''s simple and clean :)</td>', 'It seems a little bit blurry to me, maybe it was out of focus or the shutter speed was too slow? Anyway, nice photo, doesn''t "shout" zen but it''s simple and clean :)', '2010-04-26 20:07:03.000000', NULL, 1),
(5972663, 871174, 115671, '<td valign="top">This photo is a bit soft to me... nothing really seems in focus. I like the composition, however.</td>', 'This photo is a bit soft to me... nothing really seems in focus. I like the composition, however.', '2010-04-26 20:25:50.000000', NULL, 1),
(5972673, 868215, 115671, '<td valign="top">I really like the composition on this one. The only thing that is mildly distracting is the graduated border, but i''m not sure if a different border would look better on it anyway.</td>', 'I really like the composition on this one. The only thing that is mildly distracting is the graduated border, but i''m not sure if a different border would look better on it anyway.', '2010-04-26 20:28:09.000000', NULL, 1),
(5972680, 868111, 115671, '<td valign="top">Really love the idea and the execution. Also, a very harmonious composition.</td>', 'Really love the idea and the execution. Also, a very harmonious composition.', '2010-04-26 20:30:26.000000', NULL, 1),
(5972687, 869284, 115671, '<td valign="top">The details of the reflections in the upper part of the image are great :)</td>', 'The details of the reflections in the upper part of the image are great :)', '2010-04-26 20:33:46.000000', NULL, 1),
(5972699, 868224, 115671, '<td valign="top">I''m really not sure, but this might have been better if the composition wasn''t central. This way i have the feeling that the chair is staring at me instead of inviting me to look at it :)</td>', 'I''m really not sure, but this might have been better if the composition wasn''t central. This way i have the feeling that the chair is staring at me instead of inviting me to look at it :)', '2010-04-26 20:39:38.000000', NULL, 1),
(5972731, 870932, 115671, '<td valign="top">I''m not sure if you could have done anything about it under the rules, but the L and R markings are a little bit distractive here. I really like the simplicity of this apart from that tiny distraction.</td>', 'I''m not sure if you could have done anything about it under the rules, but the L and R markings are a little bit distractive here. I really like the simplicity of this apart from that tiny distraction.', '2010-04-26 20:49:48.000000', NULL, 1),
(5972777, 870782, 35602, '<td valign="top">Like the picture and the capture, but needs a bit better quality.  Need better focus I think and perhaps a better exposure.</td>', 'Like the picture and the capture, but needs a bit better quality.  Need better focus I think and perhaps a better exposure.', '2010-04-26 21:21:54.000000', NULL, 1),
(5972779, 870547, 35602, '<td valign="top">Terrific detail on the drops.  Nice color on the leaf.</td>', 'Terrific detail on the drops.  Nice color on the leaf.', '2010-04-26 21:22:57.000000', NULL, 1),
(5972794, 868536, 115671, '<td valign="top">I think the exposure could have been longer and it might have helped the overall tone of the photo. Also, the plant could have been moved more off-center to help the composition (off the vertical axis, to the left for example). Apart from that, this is one of the photos that do speak Zen to me on some level, especially the water interacting with the lower part of the plant.</td>', 'I think the exposure could have been longer and it might have helped the overall tone of the photo. Also, the plant could have been moved more off-center to help the composition (off the vertical axis, to the left for example). Apart from that, this is one of the photos that do speak Zen to me on some level, especially the water interacting with the lower part of the plant.', '2010-04-26 21:29:43.000000', NULL, 1),
(5972815, 868518, 66384, '<td valign="top">too bad you didn''t size this right. It looks like a very good photo, but it''s really too small to see the detail. (not voting on it)</td>', 'too bad you didn''t size this right. It looks like a very good photo, but it''s really too small to see the detail. (not voting on it)', '2010-04-26 21:37:28.000000', NULL, 1),
(5972858, 868367, 34171, '<td valign="top">Very Zen.</td>', 'Very Zen.', '2010-04-26 21:49:10.000000', NULL, 1),
(5972860, 868634, 66384, '<td valign="top">Very pretty scene and interesting processing. The light seems flat or lacking.</td>', 'Very pretty scene and interesting processing. The light seems flat or lacking.', '2010-04-26 21:49:29.000000', NULL, 1),
(5972905, 871075, 115671, '<td valign="top">Nice photo, but the power lines are distracting (and the title is distracting, confusing and weird at the same time, which isn''t necessarily a bad thing)</td>', 'Nice photo, but the power lines are distracting (and the title is distracting, confusing and weird at the same time, which isn''t necessarily a bad thing)', '2010-04-26 22:08:32.000000', NULL, 1),
(5972909, 871193, 66384, '<td valign="top">Extra point for the laugh.</td>', 'Extra point for the laugh.', '2010-04-26 22:09:41.000000', NULL, 1),
(5972920, 870495, 116499, '<td valign="top">This is what I initially thought of when I considered zen: high key, mostly monochromatic, with one focal point. This is a very well-done shot with a lovely focus, lovely tone, and lovely feel. The only thing I''d say is that it would work even better if the shell were slightly off center, to the left.</td>', 'This is what I initially thought of when I considered zen: high key, mostly monochromatic, with one focal point. This is a very well-done shot with a lovely focus, lovely tone, and lovely feel. The only thing I''d say is that it would work even better if the shell were slightly off center, to the left.', '2010-04-26 22:12:38.000000', NULL, 1),
(5972925, 870929, 116499, '<td valign="top">This is a compelling shot with wonderful shapes.</td>', 'This is a compelling shot with wonderful shapes.', '2010-04-26 22:14:09.000000', NULL, 1),
(5972927, 868374, 66384, '<td valign="top">The poor focus strains my eyes.</td>', 'The poor focus strains my eyes.', '2010-04-26 22:15:17.000000', NULL, 1),
(5972934, 868949, 51747, '<td valign="top">Nice interpretation!</td>', 'Nice interpretation!', '2010-04-26 22:18:12.000000', NULL, 1),
(5972935, 870799, 51747, '<td valign="top">Nicely done</td>', 'Nicely done', '2010-04-26 22:18:51.000000', NULL, 1),
(5972941, 870253, 51747, '<td valign="top">ummm yeah, really good!!</td>', 'ummm yeah, really good!!', '2010-04-26 22:19:49.000000', NULL, 1),
(5972944, 868750, 51747, '<td valign="top">I like this shot. Very peaceful and serene. I just hate titles with the challenge in them. This one would have been fine with out Zen.</td>', 'I like this shot. Very peaceful and serene. I just hate titles with the challenge in them. This one would have been fine with out Zen.', '2010-04-26 22:21:46.000000', NULL, 1),
(5972951, 868642, 51747, '<td valign="top">Very nice. This is a really good fit to the challenge.</td>', 'Very nice. This is a really good fit to the challenge.', '2010-04-26 22:22:35.000000', NULL, 1),
(5972959, 871460, 51747, '<td valign="top">This is a really good shot. It would do well in many challenges. It doesn''t speak ''Zen'' to me so much. 6</td>', 'This is a really good shot. It would do well in many challenges. It doesn''t speak ''Zen'' to me so much. 6', '2010-04-26 22:24:52.000000', NULL, 1),
(5972960, 870509, 116499, '<td valign="top">This image is really powerful and sticks out to be because it is unusual. My initial thought for a good zen photo was a high-key, mostly monochromatic photo with one central focus. This image almost completely blows that conception out of the water (heh). I love it. The DOF could have been bigger and the blacks upped, but otherwise this is a really successful image. Great job.</td>', 'This image is really powerful and sticks out to be because it is unusual. My initial thought for a good zen photo was a high-key, mostly monochromatic photo with one central focus. This image almost completely blows that conception out of the water (heh). I love it. The DOF could have been bigger and the blacks upped, but otherwise this is a really successful image. Great job.', '2010-04-26 22:24:59.000000', NULL, 1),
(5972983, 870249, 114056, '<td valign="top">Very nice shot, however i feel the sky and foreground have too much drama and detail for a zen shot. It looks almost like the image was sharpened or you used Topaz or something on it :) The photo is brilliant however :)<br/> <br/>Still gave it an 7.</td>', 'Very nice shot, however i feel the sky and foreground have too much drama and detail for a zen shot. It looks almost like the image was sharpened or you used Topaz or something on it :) The photo is brilliant however :) Still gave it an 7.', '2010-04-26 22:29:19.000000', NULL, 1),
(5972985, 869348, 114056, '<td valign="top">very zen! Love it. Excellent work.</td>', 'very zen! Love it. Excellent work.', '2010-04-26 22:29:45.000000', NULL, 1),
(5972994, 868307, 51747, '<td valign="top">WOW! Just an explosion of color here and what a cute Ladybug! This seems a little less serene than I would expect for this challenge. Still high marks for you!</td>', 'WOW! Just an explosion of color here and what a cute Ladybug! This seems a little less serene than I would expect for this challenge. Still high marks for you!', '2010-04-26 22:31:33.000000', NULL, 1),
(5972999, 869940, 51747, '<td valign="top">Well done.</td>', 'Well done.', '2010-04-26 22:33:19.000000', NULL, 1),
(5973003, 867641, 42495, '<td valign="top">Very cool photo, although it doesn''t really seem zen to me.  Not voting now, just commenting.</td>', 'Very cool photo, although it doesn''t really seem zen to me.  Not voting now, just commenting.', '2010-04-26 22:33:45.000000', NULL, 1),
(5973004, 871058, 42495, '<td valign="top">I''m not quite seeing the zen here.  Not voting now, just commenting.</td>', 'I''m not quite seeing the zen here.  Not voting now, just commenting.', '2010-04-26 22:33:48.000000', NULL, 1),
(5973007, 871605, 51747, '<td valign="top">Very cool! The only thing that would make it better for me, would be the see through border instead of black after the blue.</td>', 'Very cool! The only thing that would make it better for me, would be the see through border instead of black after the blue.', '2010-04-26 22:35:00.000000', NULL, 1),
(5973011, 870445, 42495, '<td valign="top">Finally a photo the whispers "zen".  Well done.</td>', 'Finally a photo the whispers "zen".  Well done.', '2010-04-26 22:37:22.000000', NULL, 1),
(5973015, 867641, 51747, '<td valign="top">Very creative and well executed.</td>', 'Very creative and well executed.', '2010-04-26 22:39:18.000000', NULL, 1),
