(5973026, 871270, 51747, '<td valign="top">So simple and elegant.</td>', 'So simple and elegant.', '2010-04-26 22:41:33.000000', NULL, 1),
(5973143, 869059, 57447, '<td valign="top">I really like this type of bridge.</td>', 'I really like this type of bridge.', '2010-04-26 23:47:33.000000', NULL, 1),
