(5973147, 869284, 57447, '<td valign="top">Those pigtails are zen like :)</td>', 'Those pigtails are zen like :)', '2010-04-26 23:52:25.000000', NULL, 1),
(5973226, 870706, 90323, '<td valign="top">Pretty good, if very simple. Maybe it''s the simplicity that counts. *I* would have liked this image more without the marble texture and maybe more of a stark black and white landscape.</td>', 'Pretty good, if very simple. Maybe it''s the simplicity that counts. *I* would have liked this image more without the marble texture and maybe more of a stark black and white landscape.', '2010-04-27 00:45:08.000000', NULL, 1),
(5973227, 868635, 90323, '<td valign="top">Good, but for more zen I would have forgotten the bridge and focused on the stones and water.</td>', 'Good, but for more zen I would have forgotten the bridge and focused on the stones and water.', '2010-04-27 00:45:32.000000', NULL, 1),
(5973231, 868541, 90323, '<td valign="top">I like it. A lot. Would like it more if the dude wasn''t hitting the top of the image. More space at the top pls!</td>', 'I like it. A lot. Would like it more if the dude wasn''t hitting the top of the image. More space at the top pls!', '2010-04-27 00:46:02.000000', NULL, 1),
(5973232, 870524, 90323, '<td valign="top">Perhaps to literal, but I like the lighting and color. Well done!</td>', 'Perhaps to literal, but I like the lighting and color. Well done!', '2010-04-27 00:46:21.000000', NULL, 1),
(5973233, 868799, 90323, '<td valign="top">Mmmm. Didn''t like this in black and white. Sorry.</td>', 'Mmmm. Didn''t like this in black and white. Sorry.', '2010-04-27 00:46:42.000000', NULL, 1),
(5973234, 870742, 90323, '<td valign="top">That is stark and empty. I would find it more Zen if there wasn''t the figure in the image, or if the figure was in a more intentional pose.</td>', 'That is stark and empty. I would find it more Zen if there wasn''t the figure in the image, or if the figure was in a more intentional pose.', '2010-04-27 00:47:08.000000', NULL, 1),
(5973236, 871326, 90323, '<td valign="top">Mmm. Not my fave for a zen contest. Sorry.</td>', 'Mmm. Not my fave for a zen contest. Sorry.', '2010-04-27 00:47:28.000000', NULL, 1),
