(5973612, 868062, 114056, '<td valign="top">Beautiful colours</td>', 'Beautiful colours', '2010-04-27 05:07:49.000000', NULL, 1),
(5973613, 870838, 114056, '<td valign="top">I feel your flash is a little too bright, and doesn''t match the colour of the natural light (looks too blue/cool). This makes your rocks look a little like they''ve been stuck into the shot rather than being a part of it.</td>', 'I feel your flash is a little too bright, and doesn''t match the colour of the natural light (looks too blue/cool). This makes your rocks look a little like they''ve been stuck into the shot rather than being a part of it.', '2010-04-27 05:10:18.000000', NULL, 1),
