(5975522, 870838, 114225, '<td valign="top">Good attempt. Some things that could be done to improve this: Less noise, more sharpness, and omit the use of flash.</td>', 'Good attempt. Some things that could be done to improve this: Less noise, more sharpness, and omit the use of flash.', '2010-04-27 23:35:38.000000', NULL, 1),
(5975526, 870568, 114225, '<td valign="top">I see what you were going for, but there isn''t a lot to hold ones interest. Also, the dish the candles are sitting on is a bit distracting.</td>', 'I see what you were going for, but there isn''t a lot to hold ones interest. Also, the dish the candles are sitting on is a bit distracting.', '2010-04-27 23:36:28.000000', NULL, 1),
(5975528, 868635, 114225, '<td valign="top">I like the idea here. I don''t like the high noise levels in the stones.</td>', 'I like the idea here. I don''t like the high noise levels in the stones.', '2010-04-27 23:37:15.000000', NULL, 1),
(5975529, 870783, 114225, '<td valign="top">I like what you were getting at, but the boats in the background are very distracting.</td>', 'I like what you were getting at, but the boats in the background are very distracting.', '2010-04-27 23:37:41.000000', NULL, 1),
(5975531, 870932, 114225, '<td valign="top">I like you escape, I just think the image lacks interest (for me).</td>', 'I like you escape, I just think the image lacks interest (for me).', '2010-04-27 23:38:43.000000', NULL, 1),
(5975535, 871529, 61961, '<td valign="top">A bit over exposed, but I like how the colors pop.  A straightened horizon would do wonders, I think!</td>', 'A bit over exposed, but I like how the colors pop.  A straightened horizon would do wonders, I think!', '2010-04-27 23:39:09.000000', NULL, 1),
(5975536, 870777, 114225, '<td valign="top">It''s hard for me to tell what''s going on here. It looks like a reflection, but the colorcast makes it difficult for me.</td>', 'It''s hard for me to tell what''s going on here. It looks like a reflection, but the colorcast makes it difficult for me.', '2010-04-27 23:39:47.000000', NULL, 1),
(5975541, 871317, 114225, '<td valign="top">I think you added the noise to this photo, because it looks a little strange to me. Maybe tone down the brightness of the noise (especially in the black area).</td>', 'I think you added the noise to this photo, because it looks a little strange to me. Maybe tone down the brightness of the noise (especially in the black area).', '2010-04-27 23:41:02.000000', NULL, 1),
(5975542, 870906, 114225, '<td valign="top">This is a nice photo, it just doesn''t interest me much.</td>', 'This is a nice photo, it just doesn''t interest me much.', '2010-04-27 23:41:26.000000', NULL, 1),
(5975547, 868374, 114225, '<td valign="top">A nice attempt, but the lack of focus really hurts the photo.</td>', 'A nice attempt, but the lack of focus really hurts the photo.', '2010-04-27 23:42:04.000000', NULL, 1),
