(5978137, 871228, 48263, '<td valign="top">very nice</td>', 'very nice', '2010-04-28 21:27:51.000000', NULL, 0),
(5978165, 869322, 16106, '<td valign="top">In response to a few more stray comments; The leaf leading the eye off the page creates a lot of eye movement is a challenge that was all about stillness. I''m not sure if the DOF is intentionally narrow, but a fair amount of the frame is just out of focus, which tends to kill the scoring here, especially on still life subjects. A lower angle would have given the flame more life, and a chance to see the shift in colors of the flame, and perhaps a trail of smoke, here it reads as a little mote of white. Granted you would lose the rather nice reflection in the wax, but I think it would be a good trade off.</td>', 'In response to a few more stray comments; The leaf leading the eye off the page creates a lot of eye movement is a challenge that was all about stillness. I''m not sure if the DOF is intentionally narrow, but a fair amount of the frame is just out of focus, which tends to kill the scoring here, especially on still life subjects. A lower angle would have given the flame more life, and a chance to see the shift in colors of the flame, and perhaps a trail of smoke, here it reads as a little mote of white. Granted you would lose the rather nice reflection in the wax, but I think it would be a good trade off.', '2010-04-28 21:50:01.000000', NULL, 0),
(5978219, 871605, 107867, '<td valign="top">Beautiful... looks like a watercolor painting :-) I love it :-)</td>', 'Beautiful... looks like a watercolor painting :-) I love it :-)', '2010-04-28 22:15:23.000000', NULL, 0),
